        ldaa    >CrankEventCounter
        anda    #$F8
        oraa    #$03
        staa    >CrankEventCounter
L792A:
        brset   <SyncFlags75,#$20,L793E
        ldaa    #$FF
        staa    >CrankActivityTimer
        clrb
        stab    <ATMOffset
        ldaa    <DRBPointer1
        cmpa    #$0A
        bne     L793E
