;---------------------------------------------------------------------------------------------------
; Isr_TIC3  ($7934)  -- interrupt vector: TIC3
;
; Input capture 3 interrupt: restarts the timer-overflow count ($0478) used to measure long
; periods. [reviewed]
;
; Clears $0478, enables the timer overflow interrupt and corrects the count if TCNT has already
; wrapped past the TIC3 capture. Together with Isr_TOF this gives a period measurement longer than
; one 131 ms timer cycle (needed during cranking).
;---------------------------------------------------------------------------------------------------
Isr_TIC3:
        ldx     #REGS
        clr     >Crank_0478
        ldaa    #$80
        staa    $25,x                                ; TFLG2: Timer interrupt flags 2
        bset    $24,x,#$80                           ; TMSK2: Timer interrupt mask 2 (TOI, RTII, PAOVI, PAII, prescaler)
        ldd     $0E,x                                ; TCNT: Free-running timer counter (16 bit)
        cpd     $14,x                                ; TIC3: Input capture 3 (16 bit)
        bcc     L797C
        inc     >Crank_0478
L797C:
        rti


