        ldab    >DFPART_DensityFactorPartThrottle    ; DFPART: DensityFactor for part throttle. Multiplied by MAP and the 3D table va
        mul
        nop
        nop
        nop
        pshb
        psha
        lsrd
        std     <Temp5
        ldab    <RPMRescaledfor3D
        ldaa    <MAPRescaledfor3D
        ldx     #PRTTBL_FuelFromRPMAndMAP            ; PRTTBL (FuelFromRPMAndMAP)
        jsr     >Lookup3DTableRoutine_2              ; 3D table lookup with bilinear interpolation.
        puly
        tsta
        beq     L8AD1
        jsr     >ScaleYbyA                           ; D = Y x A / 256 (unsigned fractional multiply).
        xgdy
        addd    <Temp5
        bcc     L8AD3
        ldd     #$FFFF
        bra     L8AD3

L8AD1:
        ldd     <Temp5
L8AD3:
        std     <BaseInjectorPulsewidthX
